[
  {
    "statement": "Six of nine replicated, controlled studies reported that adding fertilizer alongside seeding or planting increased vegetation cover in all or some cases.",
    "citations": [
      "3427"
    ]
  },
  {
    "statement": "Three of nine replicated, controlled studies found that adding fertilizer alongside seeding or planting resulted in no change to vegetation cover.",
    "citations": [
      "3427"
    ]
  },
  {
    "statement": "In peatlands planted with peatland species, fertilizer increased total vegetation, vascular plant and bryophyte cover in one Canadian bog.",
    "citations": [
      "1826"
    ]
  },
  {
    "statement": "In another Canadian bog restored as a fen, adding fertilizer increased sedge cover but did not affect total vegetation cover, total herb cover or Sphagnum cover.",
    "citations": [
      "1826"
    ]
  },
  {
    "statement": "A New Zealand bog reported increased cover of a sown shrub and a rush depending on the fertilizer chemical and peat preparation.",
